constraints:
3 ≤ N ≤ 10^{3}
-10^{3} ≤ arr[i] ≤ 10^{3}

expected time complexity: O(N^{2}).
expected auxiliary space: O(1).

standard_solution_code:
class Solution:

	def countTriplets(self, arr, n, sumo):
		arr.sort()
		c = 0
		for i in range(len(arr)):
			tar = sumo - arr[i]
			si = i + 1
			ei = n - 1
			while si <= ei:
				if arr[si] + arr[ei] < tar:
					c += ei - si
					si += 1
				else:
					ei -= 1
		return c
